create or replace function public.export_personal_data()returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=auth.uid();begin if uid is null then raise insufficient_privilege;end if;perform private.rate_limit('export',1);return jsonb_build_object('project_images',(select coalesce(jsonb_agg(x),'[]')from public.project_images x where user_id=uid),'paper_reports',(select coalesce(jsonb_agg(x),'[]')from public.paper_reports x where user_id=uid),'avatars',(select coalesce(jsonb_agg(x),'[]')from public.avatars x where user_id=uid),'subscriptions',(select coalesce(jsonb_agg(x),'[]')from public.subscriptions x where user_id=uid),'paper_saves',(select coalesce(jsonb_agg(x),'[]')from public.paper_saves x where user_id=uid),'follows',(select coalesce(jsonb_agg(x),'[]')from public.follows x where user_id=uid),'blocks',(select coalesce(jsonb_agg(x),'[]')from public.blocks x where user_id=uid),'helpful_votes',(select coalesce(jsonb_agg(x),'[]')from public.helpful x where user_id=uid),'reactions',(select coalesce(jsonb_agg(x),'[]')from public.reactions x where user_id=uid),'content_appeals',(select coalesce(jsonb_agg(x),'[]')from public.content_appeals x where user_id=uid),'profile',(select to_jsonb(p)from public.profiles p where id=uid),'application',(select to_jsonb(a)from public.membership_applications a where user_id=uid),'posts',(select coalesce(jsonb_agg(p),'[]')from public.posts p where author_id=uid),'comments',(select coalesce(jsonb_agg(c),'[]')from public.comments c where author_id=uid),'preferences',(select to_jsonb(p)from public.preferences p where user_id=uid),'bookmarks',(select coalesce(jsonb_agg(b),'[]')from public.bookmarks b where user_id=uid),'projects',(select coalesce(jsonb_agg(p),'[]')from public.projects p where owner_id=uid),'collaborations',(select coalesce(jsonb_agg(c),'[]')from public.collaborations c where sender_id=uid),'notifications',(select coalesce(jsonb_agg(n),'[]')from public.notifications n where user_id=uid),'reports',(select coalesce(jsonb_agg(r),'[]')from public.reports r where reporter_id=uid),'contributions',(select coalesce(jsonb_agg(c),'[]')from public.contributions c where user_id=uid));end$$;
revoke all on function public.export_personal_data()from public,anon;grant execute on function public.export_personal_data()to authenticated;
